target='((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..)).'
n=len(target)

units = {
 (32,37):  'GCAAAC',(56,84):'CCGACCACCGCGUAUUUCGCGAGAGAAGG',(101,114):'GAAUAAAAAAUAAC',
 (128,135):'GGGGUACC',(146,178):'CUCGAAGAAGGCAGGUAUCGUGAAUGGGGGGAG',
 (180,226):'GGUGAGACAGGAAGAGGACGAGGAGCUGGGACGGGGAGGGGGACGCU',(244,258):'UUGUUCCCCGAACGA',
 (297,304):'GGGGUACC',(305,336):'CACGGUCCAAACUAACAGCUGAUGUAAUUGUG',(378,386):'GAAAAAAAC',
}
